[(a)] Under the assumptions in Proposition <<ref:BLM3.4>>(a), we have

\[
[B] * [A] =\sum_{t} v^{\beta(t)} \prod_{u=1}^N \overline{
\begin{bmatrix}
a_{hu} + t_u\\
t_u
\end{bmatrix}
} \Big [A+\sum_{1\le u\le N}  t_u (E^{\theta}_{hu}-E^{\theta}_{h+1,u}) \Big ],
\]

where $t$ is summed over as in Proposition <<ref:BLM3.4>>(a) and

\begin{equation}
\beta(t) =\sum_{j\leq l} a_{h l} t_j -\sum_{j<l} a_{h+1,l}t_j + \sum_{j< l} t_jt_l
+ \delta_{h,n} \Big(\sum_{\substack{j< l \\ j+l <N+1}} t_j t_l + \sum_{j< n+1}\frac{ t_j(t_j+1)}{2} \Big).
\end{equation}

- [(b)] Under the assumptions in Proposition <<ref:BLM3.4>>(b), we have

\[
[C] * [A]
=\sum_{t} v^{\beta'(t)} \prod_{u=1}^N \overline{
\begin{bmatrix}
a_{h+1, u} + t_u\\
t_u
\end{bmatrix}
} \Big [A-\sum_{1\le u\le N}  t_u (E^{\theta}_{hu}-E^{\theta}_{h+1,u}) \Big ], \forall h<n,
\]

where $t$ is summed over as in Proposition <<ref:BLM3.4>>(b) and

\begin{equation}
\beta'(t)
=\sum_{j\geq l} a_{h+1,l}t_j
-\sum_{j> l} a_{h l} t_j
+ \sum_{j>l} t_jt_l .
\end{equation}

For $h=n$, we have

\begin{equation}
\begin{split}
&[C] * [A]=\sum_{t}v^{\beta''(t)}
\prod_{u<n+1}\overline{
\begin{bmatrix}
a_{n+1,u}+t_u+t_{N+1-u}\\
t_u
\end{bmatrix}
}
\prod_{u> n+1}\overline{
\begin{bmatrix}
a_{n+1,u}+t_u\\
t_u
\end{bmatrix}}
\\
&\cdot \prod_{i=0}^{t_{n+1}-1}
\frac{\overline{[a_{n+1,n+1}+1+2i]}}
{\overline{[i+1]}}
\Big [A-\sum_{1\le u\le N}  t_u(E^{\theta}_{nu}-
E^{\theta}_{n+1,u})\Big ],
\end{split}
\end{equation}

where

\begin{equation}
\beta''(t)
=\sum_{j\geq l} a_{h+1,l}t_j
-\sum_{j> l} a_{h l} t_j
+ \sum_{j>l} t_jt_l
- \sum_{\substack{j< l \\j+l< N+1}} t_j t_l - \sum_{j< n+1} \frac{t_j(t_j-1)}{2} +\frac{R(R-1)}{2}.
\end{equation}
